function validate([balls]) {
  if (!Array.isArray(balls) || balls.length < 1 || balls.length > 100000) return 'balls needs 1 to 100000 values.';
  if (balls.some(b => !Number.isInteger(b) || b < 1 || b > 1000000000)) return 'Each ball number is an integer from 1 to 10^9.';
