function minGroupsForValidAssignment(balls) {
  const count = new Map();
  for (const ball of balls) {
    count.set(ball, (count.get(ball) ?? 0) + 1);
  }
  const freqs = [...count.values()];
  const smallest = freqs.reduce((a, b) => Math.min(a, b));
  for (let size = smallest; size >= 1; size--) {
    let groups = 0;
    let valid = true;
    for (const freq of freqs) {
      const boxes = Math.ceil(freq / (size + 1));
      if (boxes * size > freq) {
        valid = false;
        break;
      }
      groups += boxes;
    }
    if (valid) {
      return groups;
    }
  }
  return balls.length;
}

