function minGroupsForValidAssignment(balls) {
  const freq = {};
  for (const b of balls) freq[b] = (freq[b] || 0) + 1;
  const values = Object.values(freq);
  const most = Math.max(...values);
  let answer = Infinity;
  // Try every smallest box size s; split each count into parts of size s or s + 1 by DP.
  for (let s = 1; s <= most; s++) {
    const parts = [0];
    for (let t = 1; t <= most; t++) {
      const a = t >= s ? parts[t - s] : Infinity;
      const b = t >= s + 1 ? parts[t - s - 1] : Infinity;
      parts.push(Math.min(a, b) + 1);
    }
    const total = values.reduce((sum, f) => sum + parts[f], 0);
    if (total < answer) answer = total;
  }
  return answer;
}

