function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  const distinct = size === 'large' ? 1 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * 4);
  const big = rand() < 0.5;
  const labels = [];
  while (labels.length < distinct) {
    const v = 1 + Math.floor(rand() * (big ? 1000000000 : distinct + 8));
    if (!labels.includes(v)) labels.push(v);
  }
  // Uneven weights give a mix of large and small counts per number.
  const weights = labels.map(() => 0.2 + rand());
  const total = weights.reduce((a, b) => a + b, 0);
  const balls = Array.from({ length: n }, () => {
    let r = rand() * total;
    for (let i = 0; i < labels.length; i++) {
      r -= weights[i];
      if (r < 0) return labels[i];
    }
    return labels[labels.length - 1];
  });
  return [balls];
}
